import useToggle from "../../hook/useToggle/useToggle";
import "./Nav.css";

function Nav() {
  const { toggle, changeToggle } = useToggle();

  return (
    <div className="mainNav">
      <form className="form">
        <input type="text" name="" id="" className="text" />
        <input type="submit" value="Search City" className="search" />
        <div className="radio">
          <input
            type="radio"
            id="F"
            onClick={changeToggle}
            name="temperature"
          />
          <label htmlFor="F" className="f">
            °F
          </label>
          <input
            type="radio"
            id="C"
            name="temperature"
          />
          <label htmlFor="C">°C</label>
        </div>
      </form>
    </div>
  );
}

export default Nav;
